import "../../styles/index-base.css";
import "../../styles/components/popover.css";
import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "../../lib/cn";

export function Popover(props: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

export function PopoverTrigger(props: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

type PopoverContentProps = PopoverPrimitive.Popup.Props &
  Pick<PopoverPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function PopoverContent({
  className,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="ix-positioner" side={side} sideOffset={sideOffset} align={align} alignOffset={alignOffset}>
        <PopoverPrimitive.Popup className={cn("ix-popover", className)} {...props} data-layer="flyout" />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export const PopoverTitle = PopoverPrimitive.Title;
export const PopoverDescription = PopoverPrimitive.Description;

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-positioner { z-index: var(--ix-layer-flyout); }

.ix-popover { width: 278px; padding: 12px; border-radius: var(--ix-radius-overlay); background: var(--ix-bg-flyout); box-shadow: var(--ix-shadow-flyout); outline: 0; transform-origin: var(--transform-origin); transition: opacity var(--ix-enter-duration) var(--ix-ease-out), transform var(--ix-enter-duration) var(--ix-ease-out); }

.ix-popover[data-starting-style] { opacity: 0; transform: scale(0.98); }

.ix-popover[data-ending-style] { opacity: 0; transform: scale(0.99); transition-duration: var(--ix-exit-duration); }

.ix-popover { background: var(--ix-bg-flyout); }

@media (prefers-reduced-motion: reduce) {
.ix-popover {
    transition-property: opacity;
    transition-duration: var(--ix-exit-duration);
  }

.ix-popover[data-starting-style],
.ix-popover[data-ending-style] { transform: none; }
}
}
